extern const char kSig_PlotHeatmap[] =
    "PsychImGui('ImPlot.PlotHeatmap', labelId, values [, scaleMin=0] [, scaleMax=0] [, labelFmt='%.1f'] [, boundsMin=[0 0]] [, boundsMax=[1 1]] [, spec...])";
template <typename T_>
static void tp_PlotHeatmap_1(int nlhs, mxArray** plhs, const char* v_label, const mxArray** args, int nargin, int specAt, int rows, int cols, double v_scale_min, double v_scale_max, const char* v_label_fmt, ImPlotPoint v_bounds_min, ImPlotPoint v_bounds_max) {
    (void)nlhs; (void)plhs;
    ImPlotSpec v_spec;
    mrs::getSpec(args, nargin, specAt, v_spec, sizeof(T_));
    mrs::specNoStride(v_spec, "ImPlot.PlotHeatmap");
    if (mrs::failed()) return;
    if (!mrs::allFinite((const T_*)mxGetData(args[1]), mxGetNumberOfElements(args[1]))) { mrs::fail("psychimgui:Range", "ImPlot.PlotHeatmap: the data must be finite. Replace NaN and Inf first, for example with fillmissing."); return; }
    // MATLAB stores a matrix column major, so let ImPlot read it
    // that way instead of transposing a copy.
    v_spec.Flags = (ImPlotItemFlags)(v_spec.Flags | ImPlotHeatmapFlags_ColMajor);
    ImPlot::PlotHeatmap(v_label, (const T_*)mxGetData(args[1]), rows, cols, v_scale_min, v_scale_max, v_label_fmt, v_bounds_min, v_bounds_max, v_spec);
}

