void h_ColormapScale(int nlhs, mxArray** plhs, int nargin, const mxArray** args) {
    if (nargin < 3 || nargin > 7) { mrs::usage("ColormapScale", kSig_ColormapScale); return; }
    (void)nlhs; (void)plhs; (void)args;
    mrs::StrBuf<256> b_label;
    const char* v_label = "";
    v_label = mrs::toUtf8(args[0], "label", b_label);
    double v_scale_min = (double)(0);
    v_scale_min = (double)mrs::getScalar(args[1], "scaleMin");
    double v_scale_max = (double)(0);
    v_scale_max = (double)mrs::getScalar(args[2], "scaleMax");
    ImVec2 v_size = ImVec2(0,0);
    if (nargin > 3) { double t[2] = {0, 0}; mrs::getVec(args[3], "size", t, 2); v_size = ImVec2((float)t[0], (float)t[1]); }
    mrs::StrBuf<256> b_format;
    const char* v_format = "%g";
    if (nargin > 4 && !mxIsEmpty(args[4])) v_format = mrs::toUtf8(args[4], "format", b_format);
    ImPlotColormapScaleFlags v_flags = (ImPlotColormapScaleFlags)(0);
    if (nargin > 5) v_flags = (ImPlotColormapScaleFlags)mrs::getFlags(args[5], "flags");
    ImPlotColormap v_cmap = (ImPlotColormap)(IMPLOT_AUTO);
    if (nargin > 6) v_cmap = (ImPlotColormap)mrs::getInt(args[6], "cmap");
    if (nargin > 6) mrs::checkColormap(v_cmap, true, "cmap");
    mrs::checkNumberFormat(v_format, "format", false);
    if (mrs::failed()) return;
    ImPlot::ColormapScale(v_label, v_scale_min, v_scale_max, v_size, v_format, v_flags, v_cmap);
}

